KG42.register("rules-832478696bed2ffebf9dde3c",{"id":"44-blockchain_phev_trading::v141-c-R010","paper":"44-blockchain_phev_trading","record":{"rule_id":"v141-c-R010","mechanism_id":"v141-a-M01","name":"Market payment","process_stage":"settlement","market_meaning":"The local auctioneer provides the charging-PHEV payment function and the discharging-PHEV reward function. Scope: Charging-PHEV payments and discharging-PHEV rewards in localized P2P electricity trading served by an LAG. Electricity trading precedes the charging PHEV's payment for that transaction. Scope: Charging-PHEV payment for a localized electricity transaction with a discharging PHEV. Charging PHEVs pay discharging PHEVs according to smart-meter records. Scope: Payments from charging PHEVs to discharging PHEVs for localized electricity transactions. A charging PHEV pays by transferring energy coins from its wallet to the discharging PHEV's wallet address. Scope: The payment medium and transfer method for charging-PHEV energy transactions. For charging PHEV CV_i, payment equals the sum of its buying bid prices b_{ij}^n over discharging PHEVs j. Scope: Charging-PHEV payment schedules under the local iterative double-auction pricing rules. For discharging PHEV DV_j, the reward equals the sum of (s_{ji}^n)^2/(4l_1) over charging PHEVs i, plus a minimum reward for participation in local electricity trading. Scope: Discharging-PHEV reward schedules under the local iterative double-auction pricing rules. The abruptly disconnected PHEV is held accountable and must pay a disconnection penalty. Scope: Scheduled localized P2P electricity trades in parking lots during a specified scheduling time period. Condition: A scheduled PHEV abruptly disconnects from its scheduled trade.","independence_rationale":"Relations governed by the approved function settlement.payment under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["coordination.local_operator","execution.energy_trade","settlement.payment"],"E":[{"edge_id":"v141-c-R010-E001","source":"coordination.local_operator","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R010-C001"],"evidence_ids":["v141-b-g02-E09","v141-b-g02-E10","v141-b-g03-E09"]},{"edge_id":"v141-c-R010-E002","source":"execution.energy_trade","target":"settlement.payment","type":"precedes","constraint_ids":["v141-c-R010-C002"],"evidence_ids":["v141-b-g01-e044"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Charging-PHEV payment for a localized electricity transaction with a discharging PHEV. | Charging-PHEV payment schedules under the local iterative double-auction pricing rules. | Charging-PHEV payments and discharging-PHEV rewards in localized P2P electricity trading served by an LAG. | Discharging-PHEV reward schedules under the local iterative double-auction pricing rules. | Payments from charging PHEVs to discharging PHEVs for localized electricity transactions. | Scheduled localized P2P electricity trades in parking lots during a specified scheduling time period. | The payment medium and transfer method for charging-PHEV energy transactions.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e044","v141-b-g02-E09","v141-b-g02-E10","v141-b-g02-E14","v141-b-g02-E20","v141-b-g03-E09"]},"x":[{"variable_id":"v141-c-R010-X001","symbol":"b_{ij}^n","meaning":"Buying bid price submitted to the LAG auctioneer by charging PHEV CV_i for discharging PHEV DV_j in LAG n; it is an input to the charging-PHEV payment function.","kind":"operational","domain":"nonnegative real number","unit":null,"indices":["i ∈ C","j ∈ Z","n ∈ ι"],"evidence_ids":["v141-b-g02-E08","v141-b-g02-E09","v141-b-g02-E00"]},{"variable_id":"v141-c-R010-X002","symbol":"s_{ji}^n","meaning":"Selling bid price submitted to the LAG auctioneer by discharging PHEV DV_j for charging PHEV CV_i in LAG n; it is an input to the discharging-PHEV reward function.","kind":"operational","domain":"nonnegative real number","unit":null,"indices":["j ∈ Z","i ∈ C","n ∈ ι"],"evidence_ids":["v141-b-g02-E08","v141-b-g02-E10","v141-b-g02-E00"]},{"variable_id":"v141-c-R010-X003","symbol":"pay_i(B_i^n)","meaning":"Payment amount of charging PHEV CV_i as a function of its buying-bid vector B_i^n, given by the auctioneer's payment function.","kind":"operational","domain":"real-valued payment amount","unit":null,"indices":["i ∈ C","n ∈ ι"],"evidence_ids":["v141-b-g02-E09","v141-b-g02-E14"]},{"variable_id":"v141-c-R010-X004","symbol":"Rew_j(S_j^n)","meaning":"Reward amount of discharging PHEV DV_j as a function of its selling-bid vector S_j^n, given by the auctioneer's reward function.","kind":"operational","domain":"real-valued reward amount","unit":null,"indices":["j ∈ Z","n ∈ ι"],"evidence_ids":["v141-b-g02-E10","v141-b-g02-E14"]}],"theta":[{"parameter_id":"v141-c-R010-T001","symbol":"l_1","meaning":"Positive cost factor of the discharging-PHEV cost function, also used in the denominator of the discharging-PHEV reward function.","value":{"kind":"symbolic","number_value":null,"text_value":"l_1 > 0"},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E02","v141-b-g02-E14"]},{"parameter_id":"v141-c-R010-T002","symbol":"r_j^{\\min}","meaning":"Minimum reward for discharging PHEV DV_j owing to participation in local electricity trading.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"dollars (numerical study)","indices":["j ∈ Z"],"evidence_ids":["v141-b-g02-E14","v141-b-g02-E23"]}],"phi":[{"constraint_id":"v141-c-R010-C001","kind":"procedural","role":"core","statement":"The local auctioneer provides the charging-PHEV payment function and the discharging-PHEV reward function. Scope: Charging-PHEV payments and discharging-PHEV rewards in localized P2P electricity trading served by an LAG.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E09","v141-b-g02-E10","v141-b-g03-E09"]},{"constraint_id":"v141-c-R010-C002","kind":"procedural","role":"core","statement":"Electricity trading precedes the charging PHEV's payment for that transaction. Scope: Charging-PHEV payment for a localized electricity transaction with a discharging PHEV.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e044"]},{"constraint_id":"v141-c-R010-C003","kind":"procedural","role":"core","statement":"Charging PHEVs pay discharging PHEVs according to smart-meter records. Scope: Payments from charging PHEVs to discharging PHEVs for localized electricity transactions.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e009"]},{"constraint_id":"v141-c-R010-C004","kind":"procedural","role":"core","statement":"A charging PHEV pays by transferring energy coins from its wallet to the discharging PHEV's wallet address. Scope: The payment medium and transfer method for charging-PHEV energy transactions.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e044"]},{"constraint_id":"v141-c-R010-C005","kind":"mathematical","role":"core","statement":"For charging PHEV CV_i, payment equals the sum of its buying bid prices b_{ij}^n over discharging PHEVs j. Scope: Charging-PHEV payment schedules under the local iterative double-auction pricing rules.","expression":"pay_i(B_i^n)=\\sum_{j=1}^{J}b_{ij}^n","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["v141-c-R010-X001","v141-c-R010-X003"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E09","v141-b-g02-E14"]},{"constraint_id":"v141-c-R010-C006","kind":"mathematical","role":"core","statement":"For discharging PHEV DV_j, the reward equals the sum of (s_{ji}^n)^2/(4l_1) over charging PHEVs i, plus a minimum reward for participation in local electricity trading. Scope: Discharging-PHEV reward schedules under the local iterative double-auction pricing rules.","expression":"Rew_j(S_j^n)=\\sum_{i=1}^{I}\\frac{(s_{ji}^n)^2}{4l_1}+r_j^{\\min}","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["v141-c-R010-X002","v141-c-R010-X004"],"parameter_refs":["v141-c-R010-T001","v141-c-R010-T002"],"evidence_ids":["v141-b-g02-E10","v141-b-g02-E14"]},{"constraint_id":"v141-c-R010-C007","kind":"procedural","role":"core","statement":"The abruptly disconnected PHEV is held accountable and must pay a disconnection penalty. Scope: Scheduled localized P2P electricity trades in parking lots during a specified scheduling time period. Condition: A scheduled PHEV abruptly disconnects from its scheduled trade.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E20"]}],"pi":[{"evidence_id":"v141-b-g01-e009","location":{"location_id":"src-2be1f33ba6-p02-c2r3__v141-a-M01-settlement","page":2,"printed_page":null,"section":null,"anchor_text":"n- electricity trading at hotspots: charging PHEVs, discharging ng PHEVs, and idle PHEVs. Each PHEV ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"The charging PHEVs pay to the discharging PHEVs according to the records in the smart meters."},{"evidence_id":"v141-b-g01-e044","location":{"location_id":"src-2be1f33ba6-p04-c1r3__v141-a-M01-settlement","page":4,"printed_page":null,"section":null,"anchor_text":"pected serving time to the transaction server of an LAG. The alm transaction server works as a contr","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"4) Paying and Earning Energy Coins: After electricity trading, a charging PHEV pays for the energy transaction through a wallet address of a discharging PHEV, as shown in Fig. 2. The charging PHEV transfers energy coins from its wallet to the given wallet address."},{"evidence_id":"v141-b-g02-E09","location":{"location_id":"src-2be1f33ba6-p06-c1r2__v141-a-M01-bidding","page":6,"printed_page":"3159","section":"V. ITERATIVE DOUBLE AUCTION MECHANISM","anchor_text":"A. Entities in the Double Auction Mechanism (11 1) Charging PHEVs: The bid price vector of CVi for b","equation_id":"(8)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"1) Charging PHEVs: The bid price vector of CV_i for buying energy in LAGn is B_i^n ≜ {b_{ij}^n | j ∈ Z}. All bid prices of charging PHEVs in LAGn are denoted as B^n ≜ {B_i^n | i ∈ C}. CV_i needs to solve the following optimal electricity buying problem (EB, buyer) to determine its optimal bid price: EB: max_{B_i^n} [ U_i(C_i^n) − pay_i(B_i^n) ] (8) where pay_i(B_i^n) is the payment function of CV_i given by the auctioneer."},{"evidence_id":"v141-b-g02-E10","location":{"location_id":"src-2be1f33ba6-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":"3159","section":"V. ITERATIVE DOUBLE AUCTION MECHANISM","anchor_text":"j DVj solves an optimal electricity selling problem (ES, seller) to determine its optimal bid price ","equation_id":"(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"2) Discharging PHEVs: The bid price vector of DV_j for selling electricity in LAGn is denoted as S_j^n ≜ {s_{ji}^n | i ∈ C}. The bid price matrix of selling electricity is S^n ≜ {S_j^n | j ∈ Z}. DV_j solves an optimal electricity selling problem (ES, seller) to determine its optimal bid price as follows: ES: max_{S_j^n} [ Rew_j(S_j^n) − L_j(D_j^n) ] (9) where Rew_j(S_j^n) is a reward function of DV_j given by the auctioneer."},{"evidence_id":"v141-b-g02-E14","location":{"location_id":"src-2be1f33ba6-p06-c2r3__v141-a-M01-pricing","page":6,"printed_page":"3159","section":"V. ITERATIVE DOUBLE AUCTION MECHANISM","anchor_text":"J r) payi(Bni ) = bnij, (15) j 9) I (snji)2 Rewj(Snj ) = + rminj . (16) 4l1 i he For stimulation, rm","equation_id":"(15),(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"B. Pricing Rules The payment function of CV_i and the reward function of DV_j are, respectively, expressed as pay_i(B_i^n)=∑_{j=1}^{J}b_{ij}^n, (15) Rew_j(S_j^n)=∑_{i=1}^{I}\\frac{(s_{ji}^n)^2}{4l_1}+r_j^{\\min}. (16) For stimulation, r_j^{\\min} is a minimum reward for a discharging PHEV owing to the participation in local electricity trading."},{"evidence_id":"v141-b-g02-E20","location":{"location_id":"src-2be1f33ba6-p07-c2r2__v141-a-M01-validation","page":7,"printed_page":"3160","section":"C. Algorithm Implementation","anchor_text":") multiple iterations. Here, ε determines the execution time of Algorithm 1 and accuracy of ﬁnal res","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"exception"},"source_text":"In addition, auctioneers monitor localized P2P electricity trading in real time. When some unexpected events happen, e.g., abrupt disconnection of scheduled PHEVs, a trigger will be activated. Then the auctioneers may restart Algorithm 1 and reinitialize parameters on demand. A new electricity trading procedure is executed in time. Besides, similar to that in [6], we consider that few PHEVs suddenly leave from scheduled trades in parking lots during a specified scheduling time period. The abruptly disconnected PHEVs will be held accountable and will be made pay for a penalty of disconnection. This algorithm is performed with acceptable overheads in practice with low frequency of restart."},{"evidence_id":"v141-b-g03-E09","location":{"location_id":"src-2be1f33ba6-p10-c1r1__v141-a-M01-participation","page":10,"printed_page":null,"section":null,"anchor_text":"KANG et al.: ENABLING LOCALIZED PEER-TO-PEER ELECTRICITY TRADING AMONG exploited to design a localiz","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"restatement"},"source_text":"In this model, an iterative double auction mechanism for charging and discharging PHEVs is presented to maximize social welfare. The LAGs work as auctioneers to carry out the double auction among PHEVs according to their bid prices, which does not require private information about PHEVs."},{"evidence_id":"v141-b-g02-E00","location":{"location_id":"src-2be1f33ba6-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":"3157","section":"IV. PROBLEM DEFINITION FOR ELECTRICITY TRADING","anchor_text":"s, between any charging PHEV and any discharging PHEV in the s- network [14]. A local aggregator LAG","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A set of LAGs (denoted as ι) is indexed by n, where n ∈ ι ≜ {1, 2 . . . n}. Let us denote a set of charging PHEVs in LAGn as υ ≜ (CV_i^n | i ∈ C, n ∈ ι), C = {0, 1, 2, . . . , I}. The discharging PHEVs in LAGn are denoted as ψ ≜ (DV_j^n | j ∈ Z, n ∈ ι), Z = {0, 1, 2, . . . , J}. c_i^{n,min} and c_i^{n,max} are the minimum and maximum of electricity demand for CV_i^n ∈ R in LAGn, respectively. LAGn must provide c_i^{n,min} energy to CV_i^n for normal driving. Here, c_{ij}^n is the electricity demand of CV_i^n for discharging PHEV DV_j^n in LAGn."},{"evidence_id":"v141-b-g02-E02","location":{"location_id":"src-2be1f33ba6-p05-c1r2__v141-a-M01-clearing","page":5,"printed_page":"3158","section":"IV. PROBLEM DEFINITION FOR ELECTRICITY TRADING","anchor_text":"where η is average charging efﬁciency from discharging PHEVs n is the charging willingness of CV in ","equation_id":"(2)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"For the discharging PHEVs, d_{ji}^n is the amount of electricity supply from discharging PHEV DV_j^n to CV_i^n in LAGn. The electricity supply vector of DV_j^n is D_j^n ≜ {d_{ji}^n | i ∈ R}. In LAGn, the total electricity supply of all discharging PHEVs is D^n ≜ {D_j^n | j ∈ Z}. The maximum of electricity supply for a discharging PHEV in LAGn is D_j^{n,max}. In LAGn, the cost function of DV_j^n is L_j(D_j^n)=l_1 ∑_{i=1}^{I}(d_{ji}^n)^2 + l_2 ∑_{i=1}^{I}d_{ji}^n (2) where l_1 and l_2 are cost factors. Here, l_1 > 0."},{"evidence_id":"v141-b-g02-E08","location":{"location_id":"src-2be1f33ba6-p06-c1r1__v141-a-M01-bidding","page":6,"printed_page":"3159","section":"V. ITERATIVE DOUBLE AUCTION MECHANISM","anchor_text":"KANG et al.: ENABLING LOCALIZED PEER-TO-PEER ELECTRICITY TRADING AMONG electricity, which is useful ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"In this section, an iterative double auction mechanism is proposed to elicit hidden information about PHEVs to energy brokers in order to maximize social welfare. In a hotspot, an energy broker acts as an auctioneer to perform an iterative double auction according to buying prices from charging PHEVs and selling prices from the discharging ones. In this way, the auctioneer determines the final trading prices and the amount of traded electricity, which is useful to avoid directly revealing private information of PHEVs during electricity trading. More specifically, each charging PHEV CV_i submits a bid price b_{ij} ≥ 0 for each discharging PHEV DV_j to the auctioneer. And each discharging PHEV DV_j also submits a bid price s_{ji} ≥ 0 for each charging PHEV CV_i to the auctioneer. After receiving these bid prices, the auctioneer solves an optimal energy allocation problem based on the bids from PHEVs, and thus allocates electricity for every PHEV to achieve effective market equilibrium [17]."},{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-2be1f33ba6-p08-c1r4__v141-a-M01-clearing","page":8,"printed_page":"3161","section":"B. Numerical Results","anchor_text":"pp y g parking lots (see Fig. 4). We formulate electricity consumption tra behavior of PHEV as recor","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"Therefore, we set the battery capacity of the PHEVs to 24 KWh. The minimum and maximum of electricity demand for charging PHEVs are [5, 10] KWh and [12, 18] KWh, respectively. The maximum of electricity supply for discharging PHEVs is [10, 20] KWh. The cost factors of cost function, i.e., l_1 and l_2 in (2), are set to 0.01 and 0.015, respectively. The average charging efficiency η is 0.8 and the average electricity transmission efficiency ρ is 0.9. The minimum reward for a discharging PHEV r_j^{min} randomly ranges from 1 to 2 dollars. The convergence threshold ε is 0.001. We take a parking lot with 35 charging PHEVs and 45 discharging in LAG1 as an example."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-pricing","v141-a-M01-settlement","v141-a-M01-validation"],"extras":{"decision_anchor":"settlement.payment","graph_fact_supports":[[{"evidence_id":"v141-b-g02-E09","quote":"where pay_i(B_i^n) is the payment function of CV_i given by the auctioneer."},{"evidence_id":"v141-b-g02-E10","quote":"where Rew_j(S_j^n) is a reward function of DV_j given by the auctioneer."},{"evidence_id":"v141-b-g03-E09","quote":"The LAGs work as auctioneers to carry out the double auction among PHEVs according to their bid prices"}],[{"evidence_id":"v141-b-g01-e044","quote":"After electricity trading, a charging PHEV pays for the energy transaction through a wallet address of a discharging PHEV"}],[{"evidence_id":"v141-b-g01-e009","quote":"The charging PHEVs pay to the discharging PHEVs according to the records in the smart meters."}],[{"evidence_id":"v141-b-g01-e044","quote":"a charging PHEV pays for the energy transaction through a wallet address of a discharging PHEV, as shown in Fig. 2. The charging PHEV transfers energy coins from its wallet to the given wallet address."}],[{"evidence_id":"v141-b-g02-E14","quote":"The payment function of CV_i and the reward function of DV_j are, respectively, expressed as pay_i(B_i^n)=∑_{j=1}^{J}b_{ij}^n, (15)"},{"evidence_id":"v141-b-g02-E09","quote":"The bid price vector of CV_i for buying energy in LAGn is B_i^n ≜ {b_{ij}^n | j ∈ Z}."}],[{"evidence_id":"v141-b-g02-E14","quote":"Rew_j(S_j^n)=∑_{i=1}^{I}\\frac{(s_{ji}^n)^2}{4l_1}+r_j^{\\min}. (16) For stimulation, r_j^{\\min} is a minimum reward for a discharging PHEV owing to the participation in local electricity trading."},{"evidence_id":"v141-b-g02-E10","quote":"The bid price vector of DV_j for selling electricity in LAGn is denoted as S_j^n ≜ {s_{ji}^n | i ∈ C}."}],[{"evidence_id":"v141-b-g02-E20","quote":"we consider that few PHEVs suddenly leave from scheduled trades in parking lots during a specified scheduling time period. The abruptly disconnected PHEVs will be held accountable and will be made pay for a penalty of disconnection."}]],"C2_formalization":{"graph_sha256":"462db09b8faf541194dcc0dbfdb50afe8c0d75ab1481ba544059ee17dc6374eb","applicability":"formalized","reason":"Equations (15) and (16) provide explicit source expressions for the charging-PHEV payment function and the discharging-PHEV reward function. The remaining constraints are procedural settlement, transfer, or penalty rules without supplied mathematical expressions. This formalization relies on unreviewed B candidate evidence and does not assert independent source verification.","bindings":[{"object_id":"v141-c-R010-X001","node_ids":["settlement.payment"],"edge_ids":["v141-c-R010-E001"],"rationale":"The buying bid price b_{ij}^n is an input to the charging-PHEV payment function provided by the local auctioneer; edge E001 links the auctioneer/coordinator to settlement payment."},{"object_id":"v141-c-R010-X002","node_ids":["settlement.payment"],"edge_ids":["v141-c-R010-E001"],"rationale":"The selling bid price s_{ji}^n is an input to the discharging-PHEV reward function provided by the local auctioneer; edge E001 links the auctioneer/coordinator to settlement payment."},{"object_id":"v141-c-R010-X003","node_ids":["settlement.payment"],"edge_ids":["v141-c-R010-E001"],"rationale":"The payment amount pay_i(B_i^n) is the output of the charging-PHEV payment function in the settlement node; the function is supplied by the auctioneer under edge E001."},{"object_id":"v141-c-R010-X004","node_ids":["settlement.payment"],"edge_ids":["v141-c-R010-E001"],"rationale":"The reward amount Rew_j(S_j^n) is the output of the discharging-PHEV reward function in the settlement node; the function is supplied by the auctioneer under edge E001."},{"object_id":"v141-c-R010-T001","node_ids":["settlement.payment"],"edge_ids":["v141-c-R010-E001"],"rationale":"The parameter l_1 enters the discharging-PHEV reward expression in the settlement payment node; edge E001 connects the auctioneer-provided reward function to settlement."},{"object_id":"v141-c-R010-T002","node_ids":["settlement.payment"],"edge_ids":["v141-c-R010-E001"],"rationale":"The minimum participation reward r_j^{\\min} is added in the discharging-PHEV reward expression in the settlement payment node; edge E001 connects the auctioneer-provided reward function to settlement."},{"object_id":"v141-c-R010-C005","node_ids":["settlement.payment"],"edge_ids":["v141-c-R010-E001"],"rationale":"Equation (15) formalizes the charging-PHEV payment function as provided by the auctioneer; it is bound to settlement.payment and the auctioneer-to-settlement link E001."},{"object_id":"v141-c-R010-C006","node_ids":["settlement.payment"],"edge_ids":["v141-c-R010-E001"],"rationale":"Equation (16) formalizes the discharging-PHEV reward function as provided by the auctioneer; it is bound to settlement.payment and the auctioneer-to-settlement link E001."}],"revision_requests":[]}},"quarantined_references":[]}});
